// Generate index.md, themes/*.md, llms.txt and llms-full.txt from ideas/*.md.
// Usage: node scripts/build.mjs          write the files
//        node scripts/build.mjs --check  exit 1 if any generated file is out of date
import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { ROOT, RAW_BASE, THEMES, loadIdeas } from './lib.mjs';

const check = process.argv.includes('--check');
const ideas = loadIdeas().filter(i => !i.error);
const NOTE = '<!-- Generated by scripts/build.mjs. Do not edit by hand. -->';

const line = (i, prefix) => {
  const flags = [];
  if (i.meta.kind === 'view') flags.push('view');
  if (i.meta.status === 'superseded') flags.push('superseded');
  if (i.meta.anthropic === true) flags.push('Anthropic period');
  const tail = flags.length ? ` *(${flags.join(', ')})*` : '';
  return `- ${i.meta.date} · [${i.meta.title}](${prefix}${i.file}) — ${i.meta.summary}${tail}`;
};

const out = {};

// A theme page lists practices first, then views; an empty part is left out.
const section = (list, kind, heading, note) => {
  const part = list.filter(i => i.meta.kind === kind);
  return part.length ? [heading, '', `${note} ${part.length}, newest first.`, '', ...part.map(i => line(i, '../ideas/')), ''] : [];
};

// Explains the "(Anthropic period)" flag wherever it appears.
const ANTHROPIC_NOTE = '*(Anthropic period)*: dated 2026-05-19 or later, after he [joined Anthropic](https://x.com/karpathy/status/2056753169888334312), and about Claude or Anthropic. Weigh these with that in mind.';

// Idea files link to each other by bare file name; in one combined file these must be full URLs.
const absoluteLinks = (text) => text.replace(/\]\((?!https?:)([^)\s]+\.md)\)/g, (_, rel) =>
  `](${RAW_BASE}/${rel.startsWith('../') ? rel.slice(3) : 'ideas/' + rel})`);

// llms-full.txt (built first: llms.txt states its size)
const full = [
  "# Karpathy Ideas: all ideas in one file",
  '',
  "Unofficial, curated notes on Andrej Karpathy's public ideas. Not affiliated with or endorsed by him.",
  'Summaries and Apply steps are our own words under CC BY 4.0 (Apply steps translate his idea into practice; a step marked "Our reading" or "our addition" goes further than the idea itself, and one "Our reading" line at the top of Apply marks all its steps); quotes belong to their author. Source: https://github.com/ntroccoli/karpathy-ideas',
  '',
  ANTHROPIC_NOTE,
  '',
  ...ideas.map(i => [
    '---',
    '',
    `Date: ${i.meta.date} · Kind: ${i.meta.kind} · Source: ${i.meta.url} · Themes: ${(i.meta.themes || []).join(', ')} · Status: ${i.meta.status}${i.meta.superseded_by ? ' (by ' + i.meta.superseded_by + ')' : ''}${i.meta.anthropic === true ? ' · Anthropic period' : ''}`,
    '',
    absoluteLinks(i.body.trim()),
    '',
  ].join('\n')),
].join('\n');
const fullKB = Math.round(Buffer.byteLength(full, 'utf8') / 1024);
const fullKTokens = Math.round(Buffer.byteLength(full, 'utf8') / 4000);

// index.md
const latest = ideas[0]?.meta.date ?? 'none';
out['index.md'] = [
  NOTE,
  '',
  '# Index',
  '',
  `${ideas.length} ideas, newest first. Latest source date: ${latest}.`,
  'Each line: date · title — one-line summary. Browse by topic in [themes/](themes/).',
  '',
  ANTHROPIC_NOTE,
  '',
  ...ideas.map(i => line(i, 'ideas/')),
  '',
].join('\n');

// themes/<slug>.md
for (const [slug, desc] of Object.entries(THEMES)) {
  const list = ideas.filter(i => (i.meta.themes || []).includes(slug));
  out[`themes/${slug}.md`] = [
    NOTE,
    '',
    `# Theme: ${slug}`,
    '',
    desc,
    '',
    `${list.length} ideas, newest first.`,
    '',
    ...(list.some(i => i.meta.anthropic === true) ? [ANTHROPIC_NOTE, ''] : []),
    ...(list.length ? section(list, 'practice', '## Practices', 'Ways of working you can apply.')
      .concat(section(list, 'view', '## Views', 'How he sees the field: context, not steps.')) : ['No ideas yet.', '']),
  ].join('\n');
}

// llms.txt (https://llmstxt.org)
out['llms.txt'] = [
  '# Karpathy Ideas',
  '',
  "> Unofficial, curated notes on Andrej Karpathy's public ideas about working with LLMs and AI agents. Each idea: date, source link, summary in our own words, one short quote at most, and practical Apply steps (views, his opinions and explanations, may have none). Apply steps are our translation of his idea into practice, not his words; a step marked \"Our reading\" or \"our addition\" goes further than the idea itself, and one \"Our reading\" line at the top of Apply marks all its steps.",
  '',
  'Not affiliated with or endorsed by Andrej Karpathy. Prefer ideas with `status: current`; superseded ideas link to his newer view. Quotes belong to their author: link to the source instead of reproducing more text.',
  '',
  ANTHROPIC_NOTE,
  '',
  '## Applying the ideas to a project',
  '',
  `To review a whole project, use the [project checklist](${RAW_BASE}/checklist.md), not the themes: 17 questions about agent setup and token use, how the project is built, and the product. Measure each question first (where it says "Check"), then open only the linked ideas that point to a gap.`,
  '',
  '## For a single task: how to read this cheaply',
  '',
  'Use the themes when you need ideas for one task (a prompt, a workflow, a tool), not a project review.',
  '',
  '1. Pick the 2-3 themes below that match your task and read only those theme pages (one line per idea). Each page lists practices (ways of working) first, then views (his opinions and explanations); for a task, the practices are usually enough. Read the full index only if you need everything.',
  '2. Open only the idea files you will use. Each is short: YAML front matter (title, date, url, kind, summary, themes, status and the other fields), then a `# Title` heading, a summary paragraph with no heading of its own, `## In his words` (optional, one short quote), `## Apply` (steps; views may have none) and `## Context`.',
  '3. If you can delegate, let a smaller, cheaper model or subagent do steps 1-2 and return a shortlist of idea links with one line each on why they fit. The main model then reads only the shortlisted files. This saves cost and keeps the main context clean.',
  '',
  `Relative links inside these files resolve against ${RAW_BASE}/ (for example \`../ideas/x.md\` in a theme page is ${RAW_BASE}/ideas/x.md).`,
  '',
  '## Themes',
  '',
  ...Object.entries(THEMES).map(([slug, desc]) => `- [${slug}](${RAW_BASE}/themes/${slug}.md): ${desc}`),
  '',
  '## Reference',
  '',
  `- [Index](${RAW_BASE}/index.md): every idea, one line each, newest first (larger than a theme page)`,
  `- [Agent instructions](${RAW_BASE}/AGENTS.md): file format, themes, how to read and maintain`,
  '',
  '## Optional',
  '',
  `- [All ideas in one file](${RAW_BASE}/llms-full.txt): for tools that cannot browse. About ${fullKB} KB (~${fullKTokens}k tokens), so prefer the themes when you can follow links`,
  `- [Sweep log](${RAW_BASE}/log.md): what was collected and when`,
  '',
].join('\n');

out['llms-full.txt'] = full;

// Write or check.
let stale = [];
mkdirSync(join(ROOT, 'themes'), { recursive: true });
for (const [rel, content] of Object.entries(out)) {
  const p = join(ROOT, rel);
  const old = existsSync(p) ? readFileSync(p, 'utf8').replace(/\r\n/g, '\n') : null;
  if (old === content) continue;
  stale.push(rel);
  if (!check) writeFileSync(p, content);
}
// Remove theme files that no longer correspond to a theme.
for (const f of readdirSync(join(ROOT, 'themes'))) {
  if (!out[`themes/${f}`]) {
    stale.push(`themes/${f} (orphan)`);
    if (!check) rmSync(join(ROOT, 'themes', f));
  }
}
if (check && stale.length) {
  console.error('Out of date, run node scripts/build.mjs:\n  ' + stale.join('\n  '));
  process.exit(1);
}
console.log(check ? 'Generated files are up to date.' : `Built ${ideas.length} ideas; updated: ${stale.length ? stale.join(', ') : 'nothing'}.`);
